{
  "name": "Tango控制系统代理组件",
  "name_en": "Tango Control System Proxy",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于在实验控制环境中通过 Tango 资源定位符（TRL）连接属性与命令信号。它提供数值读写、配置与读数获取、事件订阅、轮询参数设置以及数据转换等功能，常用于将实验设备信号接入上层采集、监测和自动化流程。",
  "description_en": "This is a non-physical software component used to connect attribute and command signals through Tango Resource Locators (TRLs) in laboratory control environments. It provides value read/write access, configuration and reading retrieval, event subscription, polling setup, and data conversion, and is typically used to integrate experiment device signals into higher-level acquisition, monitoring, and automation workflows.",
  "tag_hints": [
    "Tango Controls",
    "signal proxy",
    "attribute and command access",
    "event subscription",
    "polling configuration",
    "lab control middleware",
    "data conversion"
  ],
  "actions": [
    {
      "action_name": "auto-get",
      "description": "获取TRL当前值。",
      "description_en": "Get the current value from the TRL."
    },
    {
      "action_name": "auto-get_w_value",
      "description": "获取最近写入TRL的值。",
      "description_en": "Get the last value written to the TRL."
    },
    {
      "action_name": "auto-put",
      "description": "向TRL写入值。",
      "description_en": "Write a value to the TRL."
    },
    {
      "action_name": "auto-get_config",
      "description": "获取TRL配置。",
      "description_en": "Get the TRL configuration."
    },
    {
      "action_name": "auto-get_reading",
      "description": "获取TRL读数。",
      "description_en": "Get a reading from the TRL."
    },
    {
      "action_name": "auto-has_subscription",
      "description": "检查该TRL是否已订阅。",
      "description_en": "Check whether this TRL already has a subscription."
    },
    {
      "action_name": "auto-subscribe_callback",
      "description": "订阅Tango CHANGE事件并注册回调。",
      "description_en": "Subscribe to Tango CHANGE events and register a callback."
    },
    {
      "action_name": "auto-unsubscribe_callback",
      "description": "取消Tango CHANGE事件订阅。",
      "description_en": "Remove the Tango CHANGE event subscription."
    },
    {
      "action_name": "auto-set_polling",
      "description": "设置轮询参数。",
      "description_en": "Set polling parameters."
    },
    {
      "action_name": "auto-set_converter",
      "description": "设置数据转换器。",
      "description_en": "Set the data converter."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询并更新信号值。",
      "description_en": "Poll and update the signal value."
    },
    {
      "action_name": "auto-datatype_allowed",
      "description": "检查数据类型是否允许。",
      "description_en": "Check whether a datatype is allowed."
    },
    {
      "action_name": "auto-set_trl",
      "description": "设置Tango资源定位符（TRL）。",
      "description_en": "Set the Tango Resource Locator (TRL)."
    },
    {
      "action_name": "auto-source",
      "description": "获取数据源标识。",
      "description_en": "Get the source identifier."
    },
    {
      "action_name": "auto-get_datakey",
      "description": "获取数据键元信息。",
      "description_en": "Get the data key metadata."
    },
    {
      "action_name": "auto-get_value",
      "description": "获取当前值。",
      "description_en": "Get the current value."
    },
    {
      "action_name": "auto-get_setpoint",
      "description": "获取设定值。",
      "description_en": "Get the setpoint value."
    },
    {
      "action_name": "auto-set_callback",
      "description": "设置更新回调。",
      "description_en": "Set the update callback."
    },
    {
      "action_name": "auto-allow_events",
      "description": "配置是否允许事件机制。",
      "description_en": "Configure whether event-based updates are allowed."
    }
  ]
}

